        List<Reservation> kept = reservations.findAll().stream()
                .filter(r -> YearMonth.from(r.checkIn()).equals(month) && r.kept().signum() > 0)
                .sorted(Comparator.comparing(Reservation::checkIn).thenComparing(Reservation::id))
                .toList();
