        create(201, "2027-03-10", "2027-03-12", 2, "STANDARD");      // 1
        create(101, "2027-03-11", "2027-03-13", 2, "NON_REFUNDABLE"); // 2
        create(102, "2027-03-11", "2027-03-13", 2, "STANDARD");      // 3 (fica pendente)
